using System;using System.Collections.Generic;namespace TagGame.Plugins{    using UnityEngine;    using TagGame.Scripts;    public class GUI : MonoBehaviour    {        public GameObject localCube, remoteCube, flag;        private GameLogic game;        private INetwork network;        private Queue<Action> mainThreadQueue = new Queue<Action>();        [SerializeField] private string networkType = "TagGame.Plugins.MulticastingNetwork";        void Start()        {            game = new GameLogic();            network = CreateNetworkComponent(networkType);            remoteCube = GameObject.Find("CubeA");            localCube = GameObject.Find("CubeB");            flag = GameObject.Find("Flag");            remoteCube.transform.position = game.RemoteCubePos;            localCube.transform.position = game.LocalCubePos;            flag.transform.position = game.FlagPos;            game.OnLocalCubeMoved += UpdateLocalCubePos;            game.OnRemoteCubeMoved += UpdateRemoteCubePos;            game.OnFlagMoved += UpdateFlagPos;            game.OnFlagCaptured += HandleFlagCaptured;            network.OnMessageReceived += HandleNetworkMessage;            _ = network.StartListening();        }        void Update()        {            if (Input.anyKey)            {                if (Input.GetKey(KeyCode.RightArrow)) game.MoveLocalCube(0.1f, 0);                if (Input.GetKey(KeyCode.LeftArrow)) game.MoveLocalCube(-0.1f, 0);                if (Input.GetKey(KeyCode.UpArrow)) game.MoveLocalCube(0, 0.1f);                if (Input.GetKey(KeyCode.DownArrow)) game.MoveLocalCube(0, -0.1f);                network.SendMessage($"x={game.LocalCubePos.x},y={game.LocalCubePos.y},z={game.LocalCubePos.z}");                while (mainThreadQueue.Count > 0)                {                    mainThreadQueue.Dequeue()?.Invoke();                }            }        }        private void UpdateLocalCubePos(Vector3 newPos)        {            localCube.transform.position = newPos;        }        private void UpdateRemoteCubePos(Vector3 newPos)        {            remoteCube.transform.position = newPos;        }        private void UpdateFlagPos(Vector3 newPos)        {            flag.transform.position = newPos;        }        private void HandleFlagCaptured(int playerId)        {            if (playerId == 0)            {                Debug.Log("Local player scored!");            }            else if (playerId == 1)            {                Debug.Log("Remote player scored!");            }            flag.transform.position = new Vector3(0.0f, 0.0f, 0.0f); // Reset flag to the center        }        private void HandleNetworkMessage(string message)        {            string[] parts = message.Split(',');            if (parts.Length == 3)            {                float x = float.Parse(parts[0].Split('=')[1]);                float y = float.Parse(parts[1].Split('=')[1]);                float z = float.Parse(parts[2].Split('=')[1]);                game.UpdateRemoteCube(new Vector3(x, y, z));            }        }        private INetwork CreateNetworkComponent(string typeName)        {            Type type = Type.GetType(typeName);            if (type != null && typeof(INetwork).IsAssignableFrom(type))            {                return (INetwork)Activator.CreateInstance(type);            }            throw new Exception($"Cannot create network component of type {typeName}");        }        void OnDestroy()        {            network?.StopListening();        }    }}